:root {
  --bg-card: #f2ead8;
  --bg-header: #2c3e2d;
  --bg-panel: #e8dfc6;
  --bg-planet: #fffdf5;
  --bg-stamp: transparent;
  --color-title: #f7f0dc;
  --color-label: #7a6a3e;
  --color-sub: #a89c70;
  --color-key: #5a4e2e;
  --color-val: #2c1e0f;
  --color-ok: #3a7d44;
  --color-warn: #b05e00;
  --color-stamp: #8b2020;
  --color-planet-sym: #4a3520;
  --color-panel-title: #2c3e2d;
  --color-footer-bg: #ddd3b4;
  --color-border: #b8a878;
  --color-planet-border: #c8b890;
  --color-id-val: #f0d890;
}

.orrery-log {
  width: 480px;
  background-color: var(--bg-card);
  border: 2px solid var(--color-border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.log-header {
  background-color: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 3px solid var(--color-border);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--color-sub);
  text-transform: uppercase;
}

.log-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-title);
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0.03em;
}

.log-sub {
  font-size: 10px;
  color: var(--color-sub);
  font-style: italic;
  letter-spacing: 0.05em;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.gear-icon {
  font-size: 26px;
  line-height: 1;
}

.log-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.id-label {
  font-size: 8px;
  letter-spacing: 0.14em;
  color: var(--color-sub);
  text-transform: uppercase;
}

.id-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-id-val);
  letter-spacing: 0.08em;
}

.log-body {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 0;
  flex: 1;
}

.instrument-panel {
  background-color: var(--bg-panel);
  border-right: 1px solid var(--color-border);
  padding: 12px;
}

.panel-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-panel-title);
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--color-border);
}

.detail-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-list li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 4px;
}

.detail-key {
  font-size: 10px;
  color: var(--color-key);
  font-weight: 600;
  letter-spacing: 0.04em;
}

.detail-val {
  font-size: 11px;
  color: var(--color-val);
  font-weight: 700;
  text-align: right;
}

.planet-grid {
  padding: 12px;
}

.planet-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-panel-title);
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--color-border);
}

.planet-items {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.planet {
  background-color: var(--bg-planet);
  border: 1px solid var(--color-planet-border);
  border-radius: 4px;
  padding: 6px 4px;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.planet-sym {
  font-size: 16px;
  line-height: 1;
  color: var(--color-planet-sym);
}

.planet-name {
  font-size: 9px;
  font-weight: 600;
  color: var(--color-key);
  letter-spacing: 0.05em;
}

.planet-status {
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.planet-status.ok {
  color: var(--color-ok);
}

.planet-status.warn {
  color: var(--color-warn);
}

.log-footer {
  background-color: var(--color-footer-bg);
  border-top: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  padding: 8px 14px;
  gap: 0;
  position: relative;
}

.footer-section {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.footer-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-label);
}

.footer-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-val);
}

.footer-value.condition {
  color: var(--color-warn);
  font-style: italic;
}

.divider-v {
  width: 1px;
  height: 32px;
  background-color: var(--color-border);
  margin: 0 12px;
}

.stamp {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%) rotate(-12deg);
  border: 2px solid var(--color-stamp);
  color: var(--color-stamp);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  padding: 3px 7px;
  border-radius: 2px;
  opacity: 0.75;
}
